//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_analysis_request_in(value: *mut Common::AnalysisRequest_Impl) -> bool;
  fn get_analysis_request_in_num_invalid() -> u64;
  fn put_analysis_request_out(value: *mut Common::AnalysisRequest_Impl) -> bool;
}

pub fn unsafe_get_analysis_request_in() -> Option<Common::AnalysisRequest_Impl>
{
  unsafe {
    let value: *mut Common::AnalysisRequest_Impl = &mut Common::AnalysisRequest_Impl::default();
    if (get_analysis_request_in(value)) {
      return Some(*value);
    } else {
      return None;
    }
  }
}

pub fn unsafe_get_analysis_request_in_num_invalid() -> u64
{
  unsafe {
    return get_analysis_request_in_num_invalid();
  }
}

pub fn unsafe_put_analysis_request_out(value: &Common::AnalysisRequest_Impl) -> bool
{
  unsafe {
    return put_analysis_request_out(value as *const Common::AnalysisRequest_Impl as *mut Common::AnalysisRequest_Impl);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_analysis_request_in: Mutex<Option<Common::AnalysisRequest_Impl>> = Mutex::new(None);
  pub static ref OUT_analysis_request_out: Mutex<Option<Common::AnalysisRequest_Impl>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_analysis_request_in.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_analysis_request_out.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_analysis_request_in(value: *mut Common::AnalysisRequest_Impl) -> bool
{
  unsafe {
    match *IN_analysis_request_in.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        *value = v;
        return true;
      },
      None => return false,
    }
  }
}

#[cfg(test)]
pub fn get_analysis_request_in_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn put_analysis_request_out(value: *mut Common::AnalysisRequest_Impl) -> bool
{
  unsafe {
    *OUT_analysis_request_out.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
